#nullable enable // autogenerated

using System;
using System.Collections.Generic;
using System.Linq;
using MVZ2.GameContent.Buffs;
using MVZ2.Vanilla.Entities;
using MVZ2.Vanilla.Projectiles;
using MVZ2.Vanilla.Properties;
using MVZ2Logic.Entities;
using PVZEngine;
using PVZEngine.Collisions;
using PVZEngine.Definitions;
using PVZEngine.Entities;
using PVZEngine.Models;
using PVZEngine.Modifiers;
using PVZEngine.Tools;
using PVZEngine.Tools.Timing;

namespace MVZ2.GameContent.Contraptions
{
    [AutoEntityBehaviourDefinition(VanillaContraptionNames.prismPylon)]
    public class PrismPylon : EntityBehaviourDefinition
    {
        public PrismPylon(string nsp, string name) : base(nsp, name)
        {
            AddModifier(new BooleanModifier(LogicEntityProps.IS_LIGHT_SOURCE, BooleanOperator.Set, LogicContraptionProps.PROP_EVOKED));
            AddModifier(new IntModifier(EngineEntityProps.COLLISION_MASK_FRIENDLY, IntegerOperator.BitOr, EntityCollisionHelper.MASK_PROJECTILE));
        }
        public override void Update(Entity entity)
        {
            base.Update(entity);
            entity.SetAnimationFloat("CrystalAlpha", GetCrystalAlpha(entity));
            entity.SetAnimationBool("Evoked", entity.IsEvoked());
        }
        public override void PostCollision(EntityCollision collision, int state)
        {
            base.PostCollision(collision, state);
            if (state != EntityCollisionHelper.STATE_ENTER)
                return;
            var entity = collision.Entity;
            var target = collision.Other;
            if (target.Type != EntityTypes.PROJECTILE)
                return;
            if (!entity.IsFriendly(target))
                return;
            if (target.IsProjectileColliderIgnored(collision.Collider))
                return;
            var projectileID = entity.GetProjectileID();
            if (!NamespaceID.IsValid(projectileID) || target.IsEntityOf(projectileID))
                return;
            var evoked = entity.IsEvoked();
            TransformProjectile(entity, target, evoked);
        }
        public static void TransformProjectile(Entity entity, Entity projectile, bool evoked)
        {
            int count = TRANSFORM_COUNT;
            var modes = GetPossibleProjectileModes(entity, projectile, count);
            for (int i = 0; i < count; i++)
            {
                var mode = modes[i];
                var projectileID = entity.GetProjectileID();
                var position = projectile.Position;
                var velocity = projectile.Velocity * (1 + (i * 0.25f));
                if (NamespaceID.IsValid(projectileID))
                {
                    mode.Apply(entity, projectileID, projectile, position, velocity);
                }
            }
            projectile.Remove();
        }
        public static PrismPylonProjectileMode[] GetPossibleProjectileModes(Entity entity, Entity projectile, int count)
        {
            var rng = entity.RNG;
            return projectileModes.RandomTake(count, rng).ToArray();
        }
        public static float GetCrystalAlpha(Entity entity) => 0;
#warning
        public static void SetKaleidoscopeTimer(Entity entity, FrameTimer? value) => entity.SetProperty(PROP_KALEIDOSCOPE_TIMER, value);
        public static FrameTimer? GetKaleidoscopeTimer(Entity entity) => entity.GetProperty<FrameTimer>(PROP_KALEIDOSCOPE_TIMER);
        public static void SetTransformerPrism(Entity entity, EntityID? value) => entity.SetProperty(PROP_TRANSFORMER_PRISM, value);
        public static EntityID? GetTransformerPrism(Entity entity) => entity.GetProperty<EntityID>(PROP_TRANSFORMER_PRISM);
        public const int TRANSFORM_COUNT = 3;
        public static readonly VanillaBuffPropertyMeta<FrameTimer> PROP_KALEIDOSCOPE_TIMER = new VanillaBuffPropertyMeta<FrameTimer>("kaleidoscope_timer");
        public static readonly VanillaBuffPropertyMeta<EntityID> PROP_TRANSFORMER_PRISM = new VanillaBuffPropertyMeta<EntityID>("transformer_prism");
        public static readonly List<PrismPylonProjectileMode> projectileModes = new List<PrismPylonProjectileMode>()
        {
            new PrismPylonProjectileModeRed(),
            new PrismPylonProjectileModeOrange(),
            new PrismPylonProjectileModeYellow(),
            new PrismPylonProjectileModeGreen(),
            new PrismPylonProjectileModeCyan(),
            new PrismPylonProjectileModeBlue(),
            new PrismPylonProjectileModePurple(),
        };
    }
}
